head.script:
scwin.trigger1_onclick = function(e) {
    gridView1.setDisabled(true);
};
scwin.trigger2_onclick = function(e) {
    gridView1.setDisabled(false);
};
scwin.trigger3_onclick = function(e) {
    dataList1.insertRow();
};
scwin.gridView1_oncellclick = function(row, col) {
    //alert("click");
    log = "click";
};
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 true버튼을 클릭한다.
    //1. Run the sample file and click the "true" button.
    //Verify step 1. Grid view is disabled.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_dataLayer').hasClass('w2grid_disabled')", "true");
    //Test step 2. 그다음 insert버튼을 클릭한다.
    //2. Then click on the insert button.
    //Verify step 2. The fourth item is added to the grid view.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_body_tbody tr:nth-child(4)').css('display') == 'table-row'", "true");
    //Test step 3. 그다음 false버튼을 클릭한다.
    //3. Then click the false button.
    //Verify step 3. Grid view is enabled.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_dataLayer').hasClass('w2grid_disabled')", "false");
    //Test step 4. name3항목의 4번째로 추가된 버튼을 마우스로 클릭한다.
    //4. Click the fourth button of the name3 item with the mouse.
    //Verify step 4. The button is clicked.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_3_2').childNodes[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log == 'click'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = undefined;
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 27-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
